/**
 * expo-notifications stub — hooks/node_modules/ test double.
 *
 * Node.js resolves this package first for files in hooks/ because it is the
 * nearest node_modules/ directory.  Metro never reaches it: the Metro
 * blockList in metro.config.js matches hooks/node_modules/ and forces
 * fall-through to the real package in the project-root node_modules/.
 *
 * Exports (via default):
 *   _scheduled   — string[] of IDs returned by scheduleNotificationAsync
 *   _cancelled   — string[] of IDs passed to cancelScheduledNotificationAsync
 *   _requests    — full request objects (parallel-indexed with _scheduled);
 *                  each has { id, content, trigger } — trigger.seconds lets
 *                  tests reconstruct the absolute scheduled epoch
 *   _reset()              — clear all state and counters
 *   _setPushToken(t)      — override the push token
 *   _setPushTokenDelay(ms)    — add artificial delay to getExpoPushTokenAsync
 *   _setPermissionStatus(s)   — override permission status ('granted'|'denied'|'undetermined')
 *
 * Named exports (for direct import by test files):
 *   _setPermissionStatus, _setPushToken, _setPushTokenDelay
 */

const _scheduled = [];
const _cancelled = [];
const _requests  = [];
let _counter = 0;

let _pushToken = 'ExponentPushToken[stub]';
let _pushTokenDelayMs = 0;

// Mutable permission state — mutated by _setPermissionStatus below.
// Kept outside the exported functions so getPermissionsAsync closes over the
// same variable that _setPermissionStatus writes.
let _permStatus = 'granted';

export const _setPermissionStatus = (s) => { _permStatus = s; };
export const _setPushToken        = (t) => { _pushToken = t; };
export const _setPushTokenDelay   = (ms) => { _pushTokenDelayMs = ms; };

const _reset = () => {
  _scheduled.length = 0;
  _cancelled.length = 0;
  _requests.length  = 0;
  _counter = 0;
  _pushToken = 'ExponentPushToken[stub]';
  _pushTokenDelayMs = 0;
  _permStatus = 'granted';
};

export const setNotificationHandler        = () => {};
export const setNotificationChannelAsync   = async () => {};
export const getPermissionsAsync           = async () => ({
  status: _permStatus,
  granted: _permStatus === 'granted',
  canAskAgain: _permStatus !== 'denied',
});
export const requestPermissionsAsync       = async () => ({
  status: _permStatus,
  granted: _permStatus === 'granted',
  canAskAgain: false,
});
export const getExpoPushTokenAsync         = async () => {
  if (_pushTokenDelayMs > 0) await new Promise(r => setTimeout(r, _pushTokenDelayMs));
  return { data: _pushToken, type: 'expo' };
};
export const scheduleNotificationAsync     = async (req) => {
  const id = `stub-notif-${++_counter}`;
  _scheduled.push(id);
  _requests.push({ id, ...req });
  return id;
};
export const cancelScheduledNotificationAsync = async (id) => { _cancelled.push(String(id)); };
export const addNotificationResponseReceivedListener = (_cb) => ({ remove: () => {} });
export const removeNotificationSubscription = () => {};
export const AndroidImportance = { NONE: 0, MIN: 1, LOW: 2, DEFAULT: 3, HIGH: 4, MAX: 5 };

export default {
  _scheduled, _cancelled, _requests, _reset,
  _setPushToken, _setPushTokenDelay, _setPermissionStatus,
};
